package com.dreamcore.workspace;
import com.dreamcore.workspace.conversation.*;
import com.dreamcore.workspace.audience.WorkAudienceService;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class BriefingEditorialPlanTest {
 WorkAudienceService.Context audience(){return new WorkAudienceService.Context("1.0","key","OWNER","负责人","职能保障","负责人","核对收款",List.of(),List.of(),List.of(),true,false,new WorkAudienceService.Goals("保证收款工作推进","核查五店",""));}
 AgentTaskService.TopicCandidate topic(String type){return new AgentTaskService.TopicCandidate("本月情况","现有核验依据",type.equals("DATA"),"新增依据",type,"核对收款","BRIEFING","决定下一步");}
 BriefingEditorialPlan.Item item(String shape,String decision,Integer target){return new BriefingEditorialPlan.Item("governance","monthly","五店","10月1至19日",shape,decision,target,"同一问题合并，保持分别统计");}
 @Test void mergesOverlapAndAllowsMixedTypes(){var p=new BriefingEditorialPlan.Plan(UUID.randomUUID(),"key",List.of(item("COMPARISON","EMIT",null),item("COMPARISON","MERGE",0),new BriefingEditorialPlan.Item("stage","refund-followup","荔星","截至19日","STEPS","EMIT",null,"独立接续事项")));assertDoesNotThrow(()->BriefingEditorialPlan.validate(p,List.of(topic("DATA"),topic("DATA"),topic("SUGGESTION")),0,audience()));}
 @Test void rejectsDuplicateOutputAndMergeSelection(){var list=List.of(topic("DATA"),topic("DATA"));assertThrows(RuntimeException.class,()->BriefingEditorialPlan.validate(new BriefingEditorialPlan.Plan(UUID.randomUUID(),"key",List.of(item("COMPARISON","EMIT",null),item("COMPARISON","EMIT",null))),list,0,audience()));assertThrows(RuntimeException.class,()->BriefingEditorialPlan.validate(new BriefingEditorialPlan.Plan(UUID.randomUUID(),"key",List.of(item("COMPARISON","EMIT",null),item("COMPARISON","MERGE",0))),list,1,audience()));}
 @Test void rejectsMissingGoalAndWrongReader(){assertThrows(RuntimeException.class,()->BriefingEditorialPlan.validate(new BriefingEditorialPlan.Plan(UUID.randomUUID(),"other",List.of(item("COMPARISON","EMIT",null))),List.of(topic("DATA")),0,audience()));var i=new BriefingEditorialPlan.Item("invented","q","s","p","NEWS","EMIT",null,"reason");assertThrows(RuntimeException.class,()->BriefingEditorialPlan.validate(new BriefingEditorialPlan.Plan(UUID.randomUUID(),"key",List.of(i)),List.of(topic("INFO")),0,audience()));}
 @Test void componentChoiceIsEnforcedForEveryType(){for(var pair:List.of(List.of("DATA","COMPARISON","EDITORIAL"),List.of("SUGGESTION","STEPS","STEPS"),List.of("INSIGHT","NARRATIVE","EDITORIAL"),List.of("INFO","NEWS","SOURCE"),List.of("RESULT","NARRATIVE","EDITORIAL"))){var p=new BriefingPresentationPolicy.Presentation("briefing-presentation-v1",pair.get(2),pair.get(0).equals("DATA")?"GROUPED_BAR":null,null,null,List.of());var r=new BriefingContentService.Request(pair.get(0).equals("DATA")?UUID.randomUUID():null,"标题","摘要",List.of("证据"),pair.get(0),p);assertDoesNotThrow(()->BriefingEditorialPlan.delivery(item(pair.get(1),"EMIT",null),topic(pair.get(0)),r));assertThrows(RuntimeException.class,()->BriefingEditorialPlan.delivery(item(pair.get(1),"EMIT",null),topic(pair.get(0)),new BriefingContentService.Request(r.calculationArtifactId(),r.title(),r.summary(),r.analysis(),r.businessType(),null)));}}
}
